insert into public.bible_verses (id, book_key, book_name, chapter, verse, content, sort_order)
values
('1sa-30-22','1sa','사무엘상',30,22,'다윗과 함께 갔던 자들 가운데 악한 자와 불량배들이 다 이르되 그들이 우리와 함께 가지 아니하였은즉 우리가 도로 찾은 물건은 무엇이든지 그들에게 주지 말고 각자의 처자만 데리고 떠나가게 하라 하는지라',8001),
('1sa-30-23','1sa','사무엘상',30,23,'다윗이 이르되 나의 형제들아 여호와께서 우리를 보호하시고 우리를 치러 온 그 군대를 우리 손에 넘기셨은즉 그가 우리에게 주신 것을 너희가 이같이 못하리라',8002),
('1sa-30-24','1sa','사무엘상',30,24,'이 일에 누가 너희에게 듣겠느냐 전장에 내려갔던 자의 분깃이나 소유물 곁에 머물렀던 자의 분깃이 동일할지니 같이 분배할 것이니라 하고',8003),
('1sa-30-25','1sa','사무엘상',30,25,'그 날부터 다윗이 이것으로 이스라엘의 율례와 규례를 삼았더니 오늘까지 이르니라',8004),
('1sa-30-26','1sa','사무엘상',30,26,'다윗이 시글락에 이르러 전리품을 그의 친구 유다 장로들에게 보내어 이르되 보라 여호와의 원수에게서 탈취한 것을 너희에게 선사하노라 하고',8005),
('1sa-30-27','1sa','사무엘상',30,27,'벧엘에 있는 자와 남방 라못에 있는 자와 얏딜에 있는 자와',8006),
('1sa-30-28','1sa','사무엘상',30,28,'아로엘에 있는 자와 십못에 있는 자와 에스드모아에 있는 자와',8007),
('1sa-30-29','1sa','사무엘상',30,29,'라갈에 있는 자와 여라므엘 사람의 성읍들에 있는 자와 겐 사람의 성읍들에 있는 자와',8008),
('1sa-30-30','1sa','사무엘상',30,30,'홀마에 있는 자와 고라산에 있는 자와 아닥에 있는 자와',8009),
('1sa-30-31','1sa','사무엘상',30,31,'헤브론에 있는 자에게와 다윗과 그의 사람들이 왕래하던 모든 곳에 보내었더라',8010),
('1sa-31-1','1sa','사무엘상',31,1,'블레셋 사람들이 이스라엘을 치매 이스라엘 사람들이 블레셋 사람들 앞에서 도망하여 길보아 산에서 엎드러져 죽으니라',8011),
('1sa-31-2','1sa','사무엘상',31,2,'블레셋 사람들이 사울과 그의 아들들을 추격하여 사울의 아들 요나단과 아비나답과 말기수아를 죽이니라',8012),
('1sa-31-3','1sa','사무엘상',31,3,'사울이 패전하매 활 쏘는 자가 따라잡으니 사울이 그 활 쏘는 자에게 중상을 입은지라',8013),
('1sa-31-4','1sa','사무엘상',31,4,'그가 무기를 든 자에게 이르되 네 칼을 빼어 그것으로 나를 찌르라 할례 받지 않은 자들이 와서 나를 찌르고 모욕할까 두려워하노라 하나 무기를 든 자가 심히 두려워하여 감히 행하지 아니하는지라 이에 사울이 자기의 칼을 뽑아서 그 위에 엎드러지매',8014),
('1sa-31-5','1sa','사무엘상',31,5,'무기를 든 자가 사울이 죽음을 보고 자기도 자기 칼 위에 엎드러져 그와 함께 죽으니라',8015),
('1sa-31-6','1sa','사무엘상',31,6,'사울과 그의 세 아들과 무기를 든 자와 그의 모든 사람이 다 그 날에 함께 죽었더라',8016),
('1sa-31-7','1sa','사무엘상',31,7,'골짜기 저쪽에 있는 이스라엘 사람과 요단 건너쪽에 있는 자들이 이스라엘 사람들이 도망한 것과 사울과 그의 아들들이 죽었음을 보고 성읍들을 버리고 도망하매 블레셋 사람들이 이르러 거기에서 사니라',8017),
('1sa-31-8','1sa','사무엘상',31,8,'그 이튿날 블레셋 사람들이 죽은 자를 벗기러 왔다가 사울과 그의 세 아들이 길보아 산에서 죽은 것을 보고',8018),
('1sa-31-9','1sa','사무엘상',31,9,'사울의 머리를 베고 그의 갑옷을 벗기고 자기들의 신당과 백성에게 알리기 위하여 그것을 블레셋 사람들의 땅 사방에 보내고',8019),
('1sa-31-10','1sa','사무엘상',31,10,'그의 갑옷은 아스다롯의 집에 두고 그의 시체는 벧산 성벽에 못 박으매',8020),
('1sa-31-11','1sa','사무엘상',31,11,'길르앗 야베스 주민들이 블레셋 사람들이 사울에게 행한 일을 듣고',8021),
('1sa-31-12','1sa','사무엘상',31,12,'모든 장사들이 일어나 밤새도록 달려가서 사울의 시체와 그의 아들들의 시체를 벧산 성벽에서 내려 가지고 야베스에 돌아가서 거기서 불사르고',8022),
('1sa-31-13','1sa','사무엘상',31,13,'그의 뼈를 가져다가 야베스 에셀 나무 아래에 장사하고 칠 일 동안 금식하였더라',8023),
('2sa-1-1','2sa','사무엘하',1,1,'사울이 죽은 후에 다윗이 아말렉 사람을 쳐죽이고 돌아와 다윗이 시글락에서 이틀을 머물더니',8024),
('2sa-1-2','2sa','사무엘하',1,2,'사흘째 되는 날에 한 사람이 사울의 진영에서 나왔는데 그의 옷은 찢어졌고 머리에는 흙이 있더라 그가 다윗에게 나아와 땅에 엎드려 절하매',8025),
('2sa-1-3','2sa','사무엘하',1,3,'다윗이 그에게 묻되 너는 어디서 왔느냐 하니 대답하되 이스라엘 진영에서 도망하여 왔나이다 하니라',8026),
('2sa-1-4','2sa','사무엘하',1,4,'다윗이 그에게 이르되 일이 어떻게 되었느냐 너는 내게 말하라 그가 대답하되 군사가 전쟁 중에 도망하기도 하였고 무리 가운데에 엎드러져 죽은 자도 많았고 사울과 그의 아들 요나단도 죽었나이다 하는지라',8027),
('2sa-1-5','2sa','사무엘하',1,5,'다윗이 자기에게 알리는 청년에게 묻되 사울과 그의 아들 요나단이 죽은 줄을 네가 어떻게 아느냐',8028),
('2sa-1-6','2sa','사무엘하',1,6,'그에게 알리는 청년이 이르되 내가 우연히 길보아 산에 올라가 보니 사울이 자기 창에 기대고 병거와 기병은 그를 급히 따르는데',8029),
('2sa-1-7','2sa','사무엘하',1,7,'사울이 뒤로 돌아 나를 보고 부르시기로 내가 대답하되 내가 여기 있나이다 한즉',8030),
('2sa-1-8','2sa','사무엘하',1,8,'내게 이르되 너는 누구냐 하시기로 내가 그에게 대답하되 나는 아말렉 사람이니이다 한즉',8031),
('2sa-1-9','2sa','사무엘하',1,9,'또 내게 이르시되 내 목숨이 아직 내게 완전히 있으므로 내가 고통 중에 있나니 청하건대 너는 내 곁에 서서 나를 죽이라 하시기로',8032),
('2sa-1-10','2sa','사무엘하',1,10,'그가 엎드러진 후에는 살 수 없는 줄을 내가 알고 그의 곁에 서서 죽이고 그의 머리에 있는 왕관과 팔에 있는 고리를 벗겨서 내 주께로 가져왔나이다 하니라',8033),
('2sa-1-11','2sa','사무엘하',1,11,'이에 다윗이 자기 옷을 잡아 찢으매 함께 있는 모든 사람도 그리하고',8034),
('2sa-1-12','2sa','사무엘하',1,12,'사울과 그의 아들 요나단과 여호와의 백성과 이스라엘 족속이 칼에 죽음으로 말미암아 저녁 때까지 슬퍼하여 울며 금식하니라',8035),
('2sa-1-13','2sa','사무엘하',1,13,'다윗이 그 소식을 전한 청년에게 묻되 너는 어디 사람이냐 대답하되 나는 아말렉 사람 곧 외국인의 아들이니이다 하니',8036),
('2sa-1-14','2sa','사무엘하',1,14,'다윗이 그에게 이르되 네가 어찌하여 손을 들어 여호와의 기름 부음 받은 자 죽이기를 두려워하지 아니하였느냐 하고',8037),
('2sa-1-15','2sa','사무엘하',1,15,'다윗이 청년 중 한 사람을 불러 이르되 가까이 가서 그를 죽이라 하매 그가 치매 곧 죽으니라',8038),
('2sa-1-16','2sa','사무엘하',1,16,'다윗이 그에게 이르기를 네 피가 네 머리로 돌아갈지어다 네 입이 네게 대하여 증언하기를 내가 여호와의 기름 부음 받은 자를 죽였노라 함이니라 하였더라',8039),
('2sa-1-17','2sa','사무엘하',1,17,'다윗이 이 슬픈 노래로 사울과 그의 아들 요나단을 조상하고',8040),
('2sa-1-18','2sa','사무엘하',1,18,'명령하여 그것을 유다 족속에게 가르치라 하였으니 곧 활 노래라 야살의 책에 기록되었으되',8041),
('2sa-1-19','2sa','사무엘하',1,19,'이스라엘아 네 영광이 산 위에서 죽임을 당하였도다 오호라 두 용사가 엎드러졌도다',8042),
('2sa-1-20','2sa','사무엘하',1,20,'이 일을 가드에도 알리지 말며 아스글론 거리에도 전파하지 말지어다 블레셋 사람들의 딸들이 즐거워할까, 할례 받지 못한 자의 딸들이 개가를 부를까 염려로다',8043),
('2sa-1-21','2sa','사무엘하',1,21,'길보아 산들아 너희 위에 이슬과 비가 내리지 아니하며 제물 낼 밭도 없을지어다 거기서 두 용사의 방패가 버린 바 됨이니라 곧 사울의 방패가 기름 부음을 받지 아니함 같이 됨이로다',8044),
('2sa-1-22','2sa','사무엘하',1,22,'죽은 자의 피에서, 용사의 기름에서 요나단의 활이 뒤로 물러가지 아니하였으며 사울의 칼이 헛되이 돌아오지 아니하였도다',8045),
('2sa-1-23','2sa','사무엘하',1,23,'사울과 요나단이 생전에 사랑스럽고 아름다운 자이러니 죽을 때에도 서로 떠나지 아니하였도다 그들은 독수리보다 빠르고 사자보다 강하였도다',8046),
('2sa-1-24','2sa','사무엘하',1,24,'이스라엘 딸들아 사울을 슬퍼하여 울지어다 그가 붉은 옷으로 너희에게 화려하게 입혔고 금 노리개를 너희 옷에 채웠도다',8047),
('2sa-1-25','2sa','사무엘하',1,25,'오호라 두 용사가 전쟁 중에 엎드러졌도다 요나단이 네 산 위에서 죽임을 당하였도다',8048),
('2sa-1-26','2sa','사무엘하',1,26,'내 형 요나단이여 내가 그대를 애통함은 그대는 내게 심히 아름다움이라 그대가 나를 사랑함이 기이하여 여인의 사랑보다 더하였도다',8049),
('2sa-1-27','2sa','사무엘하',1,27,'오호라 두 용사가 엎드러졌으며 싸우는 무기가 망하였도다 하였더라',8050),
('2sa-2-1','2sa','사무엘하',2,1,'그 후에 다윗이 여호와께 여쭈어 아뢰되 내가 유다 한 성읍으로 올라가리이까 여호와께서 이르시되 올라가라 다윗이 아뢰되 어디로 가리이까 이르시되 헤브론으로 갈지니라',8051),
('2sa-2-2','2sa','사무엘하',2,2,'다윗이 그의 두 아내 이스르엘 여인 아히노암과 갈멜 사람 나발의 아내였던 아비가일을 데리고 그리로 올라갈 때에',8052),
('2sa-2-3','2sa','사무엘하',2,3,'또 자기와 함께 한 추종자들과 그들의 가족들을 다윗이 다 데리고 올라가서 헤브론 각 성읍에 살게 하니라',8053),
('2sa-2-4','2sa','사무엘하',2,4,'유다 사람들이 와서 거기서 다윗에게 기름을 부어 유다 족속의 왕으로 삼았더라. 어떤 사람이 다윗에게 말하여 이르되 사울을 장사한 사람은 길르앗 야베스 사람들이니이다 하매',8054),
('2sa-2-5','2sa','사무엘하',2,5,'다윗이 길르앗 야베스 사람들에게 전령들을 보내 그들에게 이르되 너희가 너희 주 사울에게 이처럼 은혜를 베풀어 그를 장사하였으니 여호와께 복을 받을지어다',8055),
('2sa-2-6','2sa','사무엘하',2,6,'너희가 이 일을 하였으니 이제 여호와께서 은혜와 진리로 너희에게 베푸시기를 원하고 나도 이 선한 일을 너희에게 갚으리니',8056),
('2sa-2-7','2sa','사무엘하',2,7,'이제 너희는 손을 강하게 하고 담대히 할지어다 너희 주 사울이 죽었고 또 유다 족속이 내게 기름을 부어 그들의 왕으로 삼았음이니라 하니라',8057),
('2sa-2-8','2sa','사무엘하',2,8,'사울의 군사령관 넬의 아들 아브넬이 이미 사울의 아들 이스보셋을 데리고 마하나임으로 건너가',8058),
('2sa-2-9','2sa','사무엘하',2,9,'길르앗과 아술과 이스르엘과 에브라임과 베냐민과 온 이스라엘의 왕으로 삼았더라',8059),
('2sa-2-10','2sa','사무엘하',2,10,'사울의 아들 이스보셋이 이스라엘 왕이 될 때에 나이가 사십 세이며 두 해 동안 왕위에 있으니라 유다 족속은 다윗을 따르니',8060),
('2sa-2-11','2sa','사무엘하',2,11,'다윗이 헤브론에서 유다 족속의 왕이 된 날 수는 칠 년 육 개월이더라',8061),
('2sa-2-12','2sa','사무엘하',2,12,'넬의 아들 아브넬과 사울의 아들 이스보셋의 신복들은 마하나임에서 나와 기브온에 이르고',8062),
('2sa-2-13','2sa','사무엘하',2,13,'스루야의 아들 요압과 다윗의 신복들도 나와 기브온 못 가에서 그들을 만나 함께 앉으니 이는 못 이쪽이요 그는 못 저쪽이라',8063),
('2sa-2-14','2sa','사무엘하',2,14,'아브넬이 요압에게 이르되 원하건대 청년들에게 일어나서 우리 앞에서 겨루게 하자 요압이 이르되 일어나게 하자 하매',8064),
('2sa-2-15','2sa','사무엘하',2,15,'그들이 일어나 그 수대로 나아가니 베냐민과 사울의 아들 이스보셋의 편에 열두 명이요 다윗의 신복 중에 열두 명이라',8065),
('2sa-2-16','2sa','사무엘하',2,16,'각기 상대방의 머리를 잡고 칼로 상대방의 옆구리를 찌르매 일제히 쓰러진지라 그러므로 그 곳을 헬갓 핫수림이라 일컬었으며 기브온에 있더라',8066),
('2sa-2-17','2sa','사무엘하',2,17,'그 날에 싸움이 심히 맹렬하더니 아브넬과 이스라엘 사람들이 다윗의 신복들 앞에서 패하니라',8067),
('2sa-2-18','2sa','사무엘하',2,18,'그 곳에 스루야의 세 아들 요압과 아비새와 아사헬이 있었는데 아사헬의 발은 들노루 같이 빠르더라',8068),
('2sa-2-19','2sa','사무엘하',2,19,'아사헬이 아브넬을 쫓아 달려가되 좌우로 치우치지 않고 아브넬의 뒤를 쫓으니',8069),
('2sa-2-20','2sa','사무엘하',2,20,'아브넬이 뒤를 돌아보며 이르되 아사헬아 너냐 대답하되 나로라',8070),
('2sa-2-21','2sa','사무엘하',2,21,'아브넬이 그에게 이르되 너는 왼쪽으로나 오른쪽으로나 가서 청년 하나를 붙잡아 그의 군복을 빼앗으라 하되 아사헬이 그렇게 하기를 원하지 아니하고 그의 뒤를 쫓으매',8071),
('2sa-2-22','2sa','사무엘하',2,22,'아브넬이 다시 아사헬에게 이르되 너는 나 쫓기를 그치라 내가 너를 쳐서 땅에 엎드러지게 할 까닭이 무엇이냐 그렇게 하면 내가 어떻게 네 형 요압을 대면하겠느냐 하되',8072),
('2sa-2-23','2sa','사무엘하',2,23,'그가 물러가기를 거절하매 아브넬이 창 뒤 끝으로 그의 배를 찌르니 창이 그의 등을 꿰뚫고 나간지라 곧 그 곳에 엎드러져 죽으매 아사헬이 엎드러져 죽은 곳에 이르는 자마다 머물러 섰더라',8073),
('2sa-2-24','2sa','사무엘하',2,24,'요압과 아비새가 아브넬의 뒤를 쫓아 기브온 거친 땅의 길 가 기아 맞은쪽 암마 산에 이를 때에 해가 졌고',8074),
('2sa-2-25','2sa','사무엘하',2,25,'베냐민 족속은 함께 모여 아브넬을 따라 한 무리를 이루고 작은 산 꼭대기에 섰더라',8075),
('2sa-2-26','2sa','사무엘하',2,26,'아브넬이 요압에게 외쳐 이르되 칼이 영원히 사람을 상하겠느냐 마침내 참혹한 일이 생길 줄을 알지 못하느냐 네가 언제 무리에게 그의 형제 쫓기를 그치라 명령하겠느냐',8076),
('2sa-2-27','2sa','사무엘하',2,27,'요압이 이르되 하나님이 살아 계심을 두고 맹세하노니 네가 말하지 아니하였더면 무리가 아침에 각각 다 돌아갔을 것이요 그의 형제를 쫓지 아니하였으리라 하고',8077),
('2sa-2-28','2sa','사무엘하',2,28,'요압이 나팔을 불매 온 무리가 머물러 서고 다시는 이스라엘을 쫓아가지 아니하고 다시는 싸우지도 아니하니라',8078),
('2sa-2-29','2sa','사무엘하',2,29,'아브넬과 그의 부하들이 밤새도록 걸어서 아라바를 지나 요단을 건너 비드론 온 땅을 지나 마하나임에 이르니라',8079),
('2sa-2-30','2sa','사무엘하',2,30,'요압이 아브넬 쫓기를 그치고 돌아와 무리를 다 모으니 다윗의 신복 중에 열아홉 명과 아사헬이 없어졌으나',8080),
('2sa-2-31','2sa','사무엘하',2,31,'다윗의 신복들이 베냐민과 아브넬에게 속한 자들을 쳐서 삼백육십 명을 죽였더라',8081),
('2sa-2-32','2sa','사무엘하',2,32,'무리가 아사헬을 들어올려 베들레헴에 있는 그의 조상 묘에 장사하고 요압과 그의 부하들이 밤새도록 걸어서 헤브론에 이른 때에 날이 밝았더라',8082),
('2sa-3-1','2sa','사무엘하',3,1,'사울의 집과 다윗의 집 사이에 전쟁이 오래매 다윗은 점점 강하여 가고 사울의 집은 점점 약하여 가니라',8083),
('2sa-3-2','2sa','사무엘하',3,2,'다윗이 헤브론에서 아들들을 낳았으되 맏아들은 암논이라 이스르엘 여인 아히노암의 소생이요',8084),
('2sa-3-3','2sa','사무엘하',3,3,'둘째는 길르압이라 갈멜 사람 나발의 아내였던 아비가일의 소생이요 셋째는 압살롬이라 그술 왕 달매의 딸 마아가의 아들이요',8085),
('2sa-3-4','2sa','사무엘하',3,4,'넷째는 아도니야라 학깃의 아들이요 다섯째는 스바댜라 아비달의 아들이요',8086),
('2sa-3-5','2sa','사무엘하',3,5,'여섯째는 이드르암이라 다윗의 아내 에글라의 소생이니 이들은 다윗이 헤브론에서 낳은 자들이더라',8087),
('2sa-3-6','2sa','사무엘하',3,6,'사울의 집과 다윗의 집 사이에 전쟁이 있는 동안에 아브넬이 사울의 집에서 점점 권세를 잡으니라',8088),
('2sa-3-7','2sa','사무엘하',3,7,'사울에게 첩이 있었으니 이름은 리스바요 아야의 딸이더라 이스보셋이 아브넬에게 이르되 네가 어찌하여 내 아버지의 첩과 통간하였느냐 하니',8089),
('2sa-3-8','2sa','사무엘하',3,8,'아브넬이 이스보셋의 말을 매우 분하게 여겨 이르되 내가 유다의 개 머리냐 내가 오늘 당신의 아버지 사울의 집과 그의 형제와 그의 친구에게 은혜를 베풀어 당신을 다윗의 손에 내주지 아니하였거늘 당신이 오늘 이 여인에게 관한 허물을 내게 돌리는도다',8090),
('2sa-3-9','2sa','사무엘하',3,9,'여호와께서 다윗에게 맹세하신 대로 내가 이루게 하지 아니하면 하나님이 아브넬에게 벌 위에 벌을 내리심이 마땅하니라',8091),
('2sa-3-10','2sa','사무엘하',3,10,'그 맹세는 곧 이 나라를 사울의 집에서 다윗에게 옮겨서 그의 왕위를 단에서 브엘세바까지 이스라엘과 유다에 세우리라 하신 것이니라 하매',8092),
('2sa-3-11','2sa','사무엘하',3,11,'이스보셋이 아브넬을 두려워하여 감히 한 마디도 대답하지 못하니라',8093),
('2sa-3-12','2sa','사무엘하',3,12,'아브넬이 자기를 대신하여 전령들을 다윗에게 보내어 이르되 이 땅이 누구의 것이니이까 또 이르되 당신은 나와 더불어 언약을 맺사이다 내 손이 당신을 도와 온 이스라엘이 당신에게 돌아가게 하리이다 하니',8094),
('2sa-3-13','2sa','사무엘하',3,13,'다윗이 이르되 좋다 내가 너와 언약을 맺거니와 내가 네게 한 가지 일을 요구하노니 나를 보러올 때에 우선 사울의 딸 미갈을 데리고 오라 그리하지 아니하면 내 얼굴을 보지 못하리라 하고',8095),
('2sa-3-14','2sa','사무엘하',3,14,'다윗이 사울의 아들 이스보셋에게 전령들을 보내 이르되 내 처 미갈을 내게로 돌리라 그는 내가 전에 블레셋 사람의 포피 백 개로 나와 정혼한 자니라 하니',8096),
('2sa-3-15','2sa','사무엘하',3,15,'이스보셋이 사람을 보내 그의 남편 라이스의 아들 발디엘에게서 그를 빼앗아 오매',8097),
('2sa-3-16','2sa','사무엘하',3,16,'그의 남편이 그와 함께 오되 울며 바후림까지 따라왔더니 아브넬이 그에게 돌아가라 하매 돌아가니라',8098),
('2sa-3-17','2sa','사무엘하',3,17,'아브넬이 이스라엘 장로들에게 말하여 이르되 너희가 여러 번 다윗을 너희의 임금으로 세우기를 구하였으니',8099),
('2sa-3-18','2sa','사무엘하',3,18,'이제 그대로 하라 여호와께서 이미 다윗에 대하여 말씀하시기를 내가 내 종 다윗의 손으로 내 백성 이스라엘을 구원하여 블레셋 사람의 손과 모든 대적의 손에서 벗어나게 하리라 하셨음이니라 하고',8100),
('2sa-3-19','2sa','사무엘하',3,19,'아브넬이 또 베냐민 사람의 귀에 말하고 아브넬이 이스라엘과 베냐민의 온 집이 선하게 여기는 모든 것을 다윗의 귀에 말하려고 헤브론으로 가니라',8101),
('2sa-3-20','2sa','사무엘하',3,20,'아브넬이 부하 이십 명과 더불어 헤브론에 이르러 다윗에게 나아가니 다윗이 아브넬과 그와 함께 한 사람을 위하여 잔치를 배설하였더라',8102),
('2sa-3-21','2sa','사무엘하',3,21,'아브넬이 다윗에게 말하되 내가 일어나 가서 온 이스라엘 무리를 내 주 왕의 앞에 모아 더불어 언약을 맺게 하고 마음에 원하시는 대로 모든 것을 다스리시게 하리이다 하니 이에 다윗이 아브넬을 보내매 그가 평안히 가니라',8103),
('2sa-3-22','2sa','사무엘하',3,22,'다윗의 신복들과 요압이 적군을 치고 크게 노략한 물건을 가지고 돌아오니 아브넬은 이미 보냄을 받아 평안히 갔고 다윗과 함께 헤브론에 있지 아니한 때라',8104),
('2sa-3-23','2sa','사무엘하',3,23,'요압 및 요압과 함께 한 모든 군사가 돌아오매 어떤 사람이 요압에게 말하여 이르되 넬의 아들 아브넬이 왕에게 왔더니 왕이 보내매 그가 평안히 갔나이다 하니',8105),
('2sa-3-24','2sa','사무엘하',3,24,'요압이 왕에게 나아가 이르되 어찌 하심이니이까 아브넬이 왕에게 나아왔거늘 어찌하여 그를 보내 잘 가게 하셨나이까',8106),
('2sa-3-25','2sa','사무엘하',3,25,'왕도 아시려니와 넬의 아들 아브넬이 온 것은 왕을 속임이라 그가 왕이 출입하는 것을 알고 왕이 하시는 모든 것을 알려 함이니이다 하고',8107),
('2sa-3-26','2sa','사무엘하',3,26,'이에 요압이 다윗에게서 나와 전령들을 보내 아브넬을 쫓아가게 하였더니 시라 우물 가에서 그를 데리고 돌아왔으나 다윗은 알지 못하였더라',8108),
('2sa-3-27','2sa','사무엘하',3,27,'아브넬이 헤브론으로 돌아오매 요압이 더불어 조용히 말하려는 듯이 그를 데리고 성문 안으로 들어가 거기서 배를 찔러 죽이니 이는 자기의 동생 아사헬의 피로 말미암음이더라',8109),
('2sa-3-28','2sa','사무엘하',3,28,'그 후에 다윗이 듣고 이르되 넬의 아들 아브넬의 피에 대하여 나와 내 나라는 여호와 앞에 영원히 무죄하니',8110),
('2sa-3-29','2sa','사무엘하',3,29,'그 죄가 요압의 머리와 그의 아버지의 온 집으로 돌아갈지어다 또 요압의 집에서 백탁병자나 나병 환자나 지팡이를 의지하는 자나 칼에 죽는 자나 양식이 떨어진 자가 끊어지지 아니할지로다 하니라',8111),
('2sa-3-30','2sa','사무엘하',3,30,'요압과 그의 동생 아비새가 아브넬을 죽인 것은 그가 기브온 전쟁에서 자기 동생 아사헬을 죽인 까닭이었더라',8112),
('2sa-3-31','2sa','사무엘하',3,31,'다윗이 요압과 및 자기와 함께 있는 모든 백성에게 이르되 너희는 옷을 찢고 굵은 베를 띠고 아브넬 앞에서 애도하라 하니라 다윗 왕이 상여를 따라가',8113),
('2sa-3-32','2sa','사무엘하',3,32,'아브넬을 헤브론에 장사하고 아브넬의 무덤에서 왕이 소리를 높여 울고 백성도 다 우니라',8114),
('2sa-3-33','2sa','사무엘하',3,33,'왕이 아브넬을 위하여 애가를 지어 이르되 아브넬의 죽음이 어찌하여 미련한 자의 죽음 같은고',8115),
('2sa-3-34','2sa','사무엘하',3,34,'네 손이 결박되지 아니하였고 네 발이 차꼬에 채이지 아니하였거늘 불의한 자식의 앞에 엎드러짐 같이 네가 엎드러졌도다 하매 온 백성이 다시 그를 슬퍼하여 우니라',8116),
('2sa-3-35','2sa','사무엘하',3,35,'석양에 뭇 백성이 나아와 다윗에게 음식을 권하니 다윗이 맹세하여 이르되 만일 내가 해 지기 전에 떡이나 다른 모든 것을 맛보면 하나님이 내게 벌 위에 벌을 내리심이 마땅하니라 하매',8117),
('2sa-3-36','2sa','사무엘하',3,36,'온 백성이 보고 기뻐하며 왕이 무슨 일을 하든지 무리가 다 기뻐하므로',8118),
('2sa-3-37','2sa','사무엘하',3,37,'이 날에야 온 백성과 온 이스라엘이 넬의 아들 아브넬을 죽인 것이 왕이 한 것이 아닌 줄을 아니라',8119),
('2sa-3-38','2sa','사무엘하',3,38,'왕이 그의 신복에게 이르되 오늘 이스라엘의 지도자요 큰 인물이 죽은 것을 알지 못하느냐',8120),
('2sa-3-39','2sa','사무엘하',3,39,'내가 기름 부음을 받은 왕이 되었으나 오늘 약하여서 스루야의 아들인 이 사람들을 제어하기가 너무 어려우니 여호와는 악행한 자에게 그 악한 대로 갚으실지로다 하니라',8121),
('2sa-4-1','2sa','사무엘하',4,1,'사울의 아들 이스보셋은 아브넬이 헤브론에서 죽었다 함을 듣고 손의 맥이 풀렸고 온 이스라엘이 놀라니라',8122),
('2sa-4-2','2sa','사무엘하',4,2,'사울의 아들 이스보셋에게 군지휘관 두 사람이 있으니 한 사람의 이름은 바아나요 한 사람의 이름은 레갑이라 베냐민 족속 브에롯 사람 림몬의 아들들이더라 브에롯도 베냐민 지파에 속하였으니',8123),
('2sa-4-3','2sa','사무엘하',4,3,'일찍이 브에롯 사람들이 깃다임으로 도망하여 오늘까지 거기에 우거함이더라',8124),
('2sa-4-4','2sa','사무엘하',4,4,'사울의 아들 요나단에게 다리 저는 아들 하나가 있었으니 이름은 므비보셋이라 전에 사울과 요나단이 죽은 소식이 이스르엘에서 올 때에 그의 나이가 다섯 살이었는데 그 유모가 안고 도망할 때 급히 도망하다가 아이가 떨어져 절게 되었더라',8125),
('2sa-4-5','2sa','사무엘하',4,5,'브에롯 사람 림몬의 아들 레갑과 바아나가 길을 떠나 볕이 쬘 때 즈음에 이스보셋의 집에 이르니 마침 그가 침상에서 낮잠을 자는지라',8126),
('2sa-4-6','2sa','사무엘하',4,6,'레갑과 그의 형제 바아나가 밀을 가지러 온 체하고 집 가운데로 들어가서 그의 배를 찌르고 도망하였더라',8127),
('2sa-4-7','2sa','사무엘하',4,7,'그들이 집에 들어가니 이스보셋이 침실에서 침상 위에 누워 있는지라 그를 쳐죽이고 목을 베어 그의 머리를 가지고 밤새도록 아라바 길로 가',8128),
('2sa-4-8','2sa','사무엘하',4,8,'헤브론에 이르러 다윗 왕에게 이스보셋의 머리를 드리며 아뢰되 왕의 생명을 해하려 하던 원수 사울의 아들 이스보셋의 머리가 여기 있나이다 여호와께서 오늘 우리 주 되신 왕의 원수를 사울과 그의 자손에게 갚으셨나이다 하니',8129),
('2sa-4-9','2sa','사무엘하',4,9,'다윗이 브에롯 사람 림몬의 아들 레갑과 그의 형제 바아나에게 대답하여 그들에게 이르되 내 생명을 여러 환난 가운데서 건지신 여호와께서 살아 계심을 두고 맹세하노니',8130),
('2sa-4-10','2sa','사무엘하',4,10,'전에 사람이 내게 알리기를 보라 사울이 죽었다 하며 그가 좋은 소식을 전하는 줄로 생각하였어도 내가 그를 잡아 시글락에서 죽여서 그것을 그 소식을 전한 갚음으로 삼았거든',8131),
('2sa-4-11','2sa','사무엘하',4,11,'하물며 악인이 의인을 그의 집 침상 위에서 죽인 것이겠느냐 그런즉 내가 악인의 피흘린 죄를 너희에게 갚아서 너희를 이 땅에서 없이하지 아니하겠느냐 하고',8132),
('2sa-4-12','2sa','사무엘하',4,12,'청년들에게 명령하매 곧 그들을 죽이고 수족을 베어 헤브론 못 가에 매달고 이스보셋의 머리를 가져다가 헤브론에서 아브넬의 무덤에 매장하였더라',8133),
('2sa-5-1','2sa','사무엘하',5,1,'이스라엘 모든 지파가 헤브론에 이르러 다윗에게 나아와 이르되 보소서 우리는 왕의 한 골육이니이다',8134),
('2sa-5-2','2sa','사무엘하',5,2,'전에 곧 사울이 우리의 왕이 되었을 때에도 이스라엘을 거느려 출입하게 하신 분은 왕이시었고 여호와께서도 왕에게 말씀하시기를 네가 내 백성 이스라엘의 목자가 되며 네가 이스라엘의 주권자가 되리라 하셨나이다 하니라',8135),
('2sa-5-3','2sa','사무엘하',5,3,'이에 이스라엘 모든 장로가 헤브론에 이르러 왕에게 나아오매 다윗 왕이 헤브론에서 여호와 앞에 그들과 언약을 맺으매 그들이 다윗에게 기름을 부어 이스라엘 왕으로 삼으니라',8136),
('2sa-5-4','2sa','사무엘하',5,4,'다윗이 나이가 삼십 세에 왕위에 올라 사십 년 동안 다스렸으되',8137),
('2sa-5-5','2sa','사무엘하',5,5,'헤브론에서 칠 년 육 개월 동안 유다를 다스렸고 예루살렘에서 삼십삼 년 동안 온 이스라엘과 유다를 다스렸더라',8138),
('2sa-5-6','2sa','사무엘하',5,6,'왕과 그의 부하들이 예루살렘으로 가서 그 땅 주민 여부스 사람을 치려 하매 그 사람들이 다윗에게 이르되 네가 결코 이리로 들어오지 못하리라 맹인과 다리 저는 자라도 너를 물리치리라 하니 그들 생각에는 다윗이 이리로 들어오지 못하리라 함이나',8139),
('2sa-5-7','2sa','사무엘하',5,7,'다윗이 시온 산성을 빼앗았으니 이는 다윗 성이더라',8140),
('2sa-5-8','2sa','사무엘하',5,8,'그 날에 다윗이 이르기를 누구든지 여부스 사람을 치거든 물 긷는 데로 올라가서 다윗의 마음에 미워하는 다리 저는 사람과 맹인을 치라 하였으므로 속담이 되어 이르기를 맹인과 다리 저는 사람은 집에 들어오지 못하리라 하더라',8141),
('2sa-5-9','2sa','사무엘하',5,9,'다윗이 그 산성에 살면서 다윗 성이라 이름하고 다윗이 밀로에서부터 안으로 성을 둘러 쌓으니라',8142),
('2sa-5-10','2sa','사무엘하',5,10,'만군의 하나님 여호와께서 함께 계시니 다윗이 점점 강성하여 가니라',8143),
('2sa-5-11','2sa','사무엘하',5,11,'두로 왕 히람이 다윗에게 사절들과 백향목과 목수와 석수를 보내매 그들이 다윗을 위하여 집을 지으니',8144),
('2sa-5-12','2sa','사무엘하',5,12,'다윗이 여호와께서 자기를 세우사 이스라엘 왕으로 삼으신 것과 그의 백성 이스라엘을 위하여 그 나라를 높이신 것을 알았더라',8145),
('2sa-5-13','2sa','사무엘하',5,13,'다윗이 헤브론에서 올라온 후에 예루살렘에서 처첩들을 더 두었으므로 아들과 딸들이 또 다윗에게서 나니',8146),
('2sa-5-14','2sa','사무엘하',5,14,'예루살렘에서 그에게서 난 자들의 이름은 삼무아와 소밥과 나단과 솔로몬과',8147),
('2sa-5-15','2sa','사무엘하',5,15,'입할과 엘리수아와 네벡과 야비아와',8148),
('2sa-5-16','2sa','사무엘하',5,16,'엘리사마와 엘랴다와 엘리벨렛이었더라',8149),
('2sa-5-17','2sa','사무엘하',5,17,'이스라엘이 다윗에게 기름을 부어 이스라엘 왕으로 삼았다 함을 블레셋 사람들이 듣고 블레셋 사람들이 다윗을 찾으러 다 올라오매 다윗이 듣고 요새로 나가니라',8150),
('2sa-5-18','2sa','사무엘하',5,18,'블레셋 사람들이 이미 이르러 르바임 골짜기에 가득한지라',8151),
('2sa-5-19','2sa','사무엘하',5,19,'다윗이 여호와께 여쭈어 이르되 내가 블레셋 사람에게로 올라가리이까 여호와께서 그들을 내 손에 넘기시겠나이까 하니 여호와께서 다윗에게 말씀하시되 올라가라 내가 반드시 블레셋 사람을 네 손에 넘기리라 하신지라',8152),
('2sa-5-20','2sa','사무엘하',5,20,'다윗이 바알브라심에 이르러 거기서 그들을 치고 다윗이 말하되 여호와께서 물을 흩음 같이 내 앞에서 내 대적을 흩으셨다 하므로 그 곳 이름을 바알브라심이라 부르니라',8153),
('2sa-5-21','2sa','사무엘하',5,21,'거기서 블레셋 사람들이 그들의 우상을 버렸으므로 다윗과 그의 부하들이 치우니라',8154),
('2sa-5-22','2sa','사무엘하',5,22,'블레셋 사람들이 다시 올라와서 르바임 골짜기에 가득한지라',8155),
('2sa-5-23','2sa','사무엘하',5,23,'다윗이 여호와께 여쭈니 이르시되 올라가지 말고 그들 뒤로 돌아서 뽕나무 수풀 맞은편에서 그들을 기습하되',8156),
('2sa-5-24','2sa','사무엘하',5,24,'뽕나무 꼭대기에서 걸음 걷는 소리가 들리거든 곧 공격하라 그 때에 여호와가 너보다 앞서 나아가서 블레셋 군대를 치리라 하신지라',8157),
('2sa-5-25','2sa','사무엘하',5,25,'이에 다윗이 여호와의 명령대로 행하여 블레셋 사람을 쳐서 게바에서 게셀까지 이르니라',8158),
('2sa-6-1','2sa','사무엘하',6,1,'다윗이 이스라엘에서 뽑은 무리 삼만 명을 다시 모으고',8159),
('2sa-6-2','2sa','사무엘하',6,2,'다윗이 일어나 자기와 함께 있는 모든 사람과 더불어 바알레유다로 가서 거기서 하나님의 궤를 메어 오려 하니 그 궤는 그룹들 사이에 좌정하신 만군의 여호와의 이름으로 불리는 것이라',8160),
('2sa-6-3','2sa','사무엘하',6,3,'그들이 하나님의 궤를 새 수레에 싣고 산에 있는 아비나답의 집에서 나오는데 아비나답의 아들 웃사와 아효가 그 새 수레를 모니라',8161),
('2sa-6-4','2sa','사무엘하',6,4,'그들이 산에 있는 아비나답의 집에서 하나님의 궤를 싣고 나올 때에 아효는 궤 앞에서 가고',8162),
('2sa-6-5','2sa','사무엘하',6,5,'다윗과 이스라엘 온 족속은 잣나무로 만든 여러 가지 악기와 수금과 비파와 소고와 양금과 제금으로 여호와 앞에서 연주하더라',8163),
('2sa-6-6','2sa','사무엘하',6,6,'그들이 나곤의 타작 마당에 이르러서는 소들이 뛰므로 웃사가 손을 들어 하나님의 궤를 붙들었더니',8164),
('2sa-6-7','2sa','사무엘하',6,7,'여호와 하나님이 웃사가 잘못함으로 말미암아 진노하사 그를 그 곳에서 치시니 그가 거기 하나님의 궤 곁에서 죽으니라',8165),
('2sa-6-8','2sa','사무엘하',6,8,'여호와께서 웃사를 치시므로 다윗이 분하여 그 곳을 베레스웃사라 부르니 그 이름이 오늘까지 이르니라',8166),
('2sa-6-9','2sa','사무엘하',6,9,'다윗이 그 날에 여호와를 두려워하여 이르되 여호와의 궤가 어찌 내게로 오리요 하고',8167),
('2sa-6-10','2sa','사무엘하',6,10,'다윗이 여호와의 궤를 옮겨 다윗 성 자기에게로 메어 가기를 즐겨하지 아니하고 가드 사람 오벧에돔의 집으로 메어 간지라',8168),
('2sa-6-11','2sa','사무엘하',6,11,'여호와의 궤가 가드 사람 오벧에돔의 집에 석 달을 있었는데 여호와께서 오벧에돔과 그의 온 집에 복을 주시니라',8169),
('2sa-6-12','2sa','사무엘하',6,12,'어떤 사람이 다윗 왕에게 아뢰어 이르되 여호와께서 하나님의 궤로 말미암아 오벧에돔의 집과 그의 모든 소유에 복을 주셨다 한지라 다윗이 가서 하나님의 궤를 기쁨으로 메고 오벧에돔의 집에서 다윗 성으로 올라갈새',8170),
('2sa-6-13','2sa','사무엘하',6,13,'여호와의 궤를 멘 사람들이 여섯 걸음을 가매 다윗이 소와 살진 송아지로 제사를 드리고',8171),
('2sa-6-14','2sa','사무엘하',6,14,'다윗이 여호와 앞에서 힘을 다하여 춤을 추는데 그 때에 다윗이 베 에봇을 입었더라',8172),
('2sa-6-15','2sa','사무엘하',6,15,'다윗과 온 이스라엘 족속이 즐거이 환호하며 나팔을 불고 여호와의 궤를 메어오니라',8173),
('2sa-6-16','2sa','사무엘하',6,16,'여호와의 궤가 다윗 성으로 들어올 때에 사울의 딸 미갈이 창으로 내다보다가 다윗 왕이 여호와 앞에서 뛰놀며 춤추는 것을 보고 심중에 그를 업신여기니라',8174),
('2sa-6-17','2sa','사무엘하',6,17,'여호와의 궤를 메고 들어가서 다윗이 그것을 위하여 친 장막 가운데 그 준비한 자리에 그것을 두매 다윗이 번제와 화목제를 여호와 앞에 드리니라',8175),
('2sa-6-18','2sa','사무엘하',6,18,'다윗이 번제와 화목제 드리기를 마치고 만군의 여호와의 이름으로 백성에게 축복하고',8176),
('2sa-6-19','2sa','사무엘하',6,19,'모든 백성 곧 온 이스라엘 무리에게 남녀를 막론하고 떡 한 개와 고기 한 조각과 건포도 떡 한 덩이씩 나누어 주매 모든 백성이 각기 집으로 돌아가니라',8177),
('2sa-6-20','2sa','사무엘하',6,20,'다윗이 자기의 가족에게 축복하러 돌아오매 사울의 딸 미갈이 나와서 다윗을 맞으며 이르되 이스라엘 왕이 오늘 어떻게 영화로우신지 방탕한 자가 염치 없이 자기의 몸을 드러내는 것처럼 오늘 그의 신복의 계집종의 눈앞에서 몸을 드러내셨도다 하니',8178),
('2sa-6-21','2sa','사무엘하',6,21,'다윗이 미갈에게 이르되 이는 여호와 앞에서 한 것이니라 그가 네 아버지와 그의 온 집을 버리시고 나를 택하사 나를 여호와의 백성 이스라엘의 주권자로 삼으셨으니 내가 여호와 앞에서 뛰놀리라',8179),
('2sa-6-22','2sa','사무엘하',6,22,'내가 이보다 더 낮아져서 스스로 천하게 보일지라도 네가 말한 바 계집종에게는 내가 높임을 받으리라 한지라',8180),
('2sa-6-23','2sa','사무엘하',6,23,'그러므로 사울의 딸 미갈이 죽는 날까지 그에게 자식이 없으니라',8181),
('2sa-7-1','2sa','사무엘하',7,1,'여호와께서 주위의 모든 원수를 무찌르사 왕으로 궁에 평안히 살게 하신 때에',8182),
('2sa-7-2','2sa','사무엘하',7,2,'왕이 선지자 나단에게 이르되 볼지어다 나는 백향목 궁에 살거늘 하나님의 궤는 휘장 가운데에 있도다',8183),
('2sa-7-3','2sa','사무엘하',7,3,'나단이 왕께 아뢰되 여호와께서 왕과 함께 계시니 마음에 있는 모든 것을 행하소서 하니라',8184),
('2sa-7-4','2sa','사무엘하',7,4,'그 밤에 여호와의 말씀이 나단에게 임하여 이르시되',8185),
('2sa-7-5','2sa','사무엘하',7,5,'가서 내 종 다윗에게 말하기를 여호와께서 이와 같이 말씀하시되 네가 나를 위하여 내가 살 집을 건축하겠느냐',8186),
('2sa-7-6','2sa','사무엘하',7,6,'내가 이스라엘 자손을 애굽에서 인도하여 내던 날부터 오늘까지 집에 살지 아니하고 장막과 성막 안에서 다녔나니',8187),
('2sa-7-7','2sa','사무엘하',7,7,'이스라엘 자손과 더불어 다니는 모든 곳에서 내가 내 백성 이스라엘을 먹이라고 명령한 이스라엘 어느 지파들 가운데 하나에게 내가 말하기를 너희가 어찌하여 나를 위하여 백향목 집을 건축하지 아니하였느냐고 말하였느냐',8188),
('2sa-7-8','2sa','사무엘하',7,8,'그러므로 이제 내 종 다윗에게 이와 같이 말하라 만군의 여호와께서 이와 같이 말씀하시기를 내가 너를 목장 곧 양을 따르는 데에서 데려다가 내 백성 이스라엘의 주권자로 삼고',8189),
('2sa-7-9','2sa','사무엘하',7,9,'네가 가는 모든 곳에서 내가 너와 함께 있어 네 모든 원수를 네 앞에서 멸하였은즉 땅에서 위대한 자들의 이름 같이 네 이름을 위대하게 만들어 주리라',8190),
('2sa-7-10','2sa','사무엘하',7,10,'내가 또 내 백성 이스라엘을 위하여 한 곳을 정하여 그를 심고 그를 거주하게 하고 다시 옮기지 못하게 하며 악한 종류로 전과 같이 그들을 해하지 못하게 하여',8191),
('2sa-7-11','2sa','사무엘하',7,11,'전에 내가 사사에게 명령하여 내 백성 이스라엘을 다스리던 때와 같지 아니하게 하고 너를 모든 원수에게서 벗어나 편히 쉬게 하리라 여호와가 또 네게 이르노니 여호와가 너를 위하여 집을 짓고',8192),
('2sa-7-12','2sa','사무엘하',7,12,'네 수한이 차서 네 조상들과 함께 누울 때에 내가 네 몸에서 날 네 씨를 네 뒤에 세워 그의 나라를 견고하게 하리라',8193),
('2sa-7-13','2sa','사무엘하',7,13,'그는 내 이름을 위하여 집을 건축할 것이요 나는 그의 나라 왕위를 영원히 견고하게 하리라',8194),
('2sa-7-14','2sa','사무엘하',7,14,'나는 그에게 아버지가 되고 그는 내게 아들이 되리니 그가 만일 죄를 범하면 내가 사람의 매와 인생의 채찍으로 징계하려니와',8195),
('2sa-7-15','2sa','사무엘하',7,15,'내가 네 앞에서 물러나게 한 사울에게서 내 은총을 빼앗은 것처럼 그에게서 빼앗지는 아니하리라',8196),
('2sa-7-16','2sa','사무엘하',7,16,'네 집과 네 나라가 내 앞에서 영원히 보전되고 네 왕위가 영원히 견고하리라 하셨다 하라',8197),
('2sa-7-17','2sa','사무엘하',7,17,'나단이 이 모든 말씀들과 이 모든 계시대로 다윗에게 말하니라',8198),
('2sa-7-18','2sa','사무엘하',7,18,'다윗 왕이 여호와 앞에 들어가 앉아서 이르되 주 여호와여 나는 누구이오며 내 집은 무엇이기에 나를 여기까지 이르게 하셨나이까',8199),
('2sa-7-19','2sa','사무엘하',7,19,'주 여호와여 주께서 이것을 오히려 적게 여기시고 또 종의 집에 있을 먼 장래의 일까지도 말씀하셨나이다 주 여호와여 이것이 사람의 법이니이다',8200),
('2sa-7-20','2sa','사무엘하',7,20,'주 여호와는 주의 종을 아시오니 다윗이 다시 주께 무슨 말씀을 하오리이까',8201),
('2sa-7-21','2sa','사무엘하',7,21,'주의 말씀으로 말미암아 주의 뜻대로 이 모든 큰 일을 행하사 주의 종에게 알게 하셨나이다',8202),
('2sa-7-22','2sa','사무엘하',7,22,'그런즉 주 여호와여 이러므로 주는 위대하시니 이는 우리 귀로 들은 대로는 주와 같은 이가 없고 주 외에는 신이 없음이니이다',8203),
('2sa-7-23','2sa','사무엘하',7,23,'땅의 어느 한 나라가 주의 백성 이스라엘과 같으리이까 하나님이 가서 구속하사 자기 백성으로 삼아 주의 명성을 내시며 그들을 위하여 큰 일을, 주의 땅을 위하여 두려운 일을 애굽과 많은 나라들과 그의 신들에게서 구속하신 백성 앞에서 행하셨사오며',8204),
('2sa-7-24','2sa','사무엘하',7,24,'주께서 주의 백성 이스라엘을 세우사 영원히 주의 백성으로 삼으셨사오니 여호와여 주께서 그들의 하나님이 되셨나이다',8205),
('2sa-7-25','2sa','사무엘하',7,25,'여호와 하나님이여 이제 주의 종과 종의 집에 대하여 말씀하신 것을 영원히 세우셨사오며 말씀하신 대로 행하사',8206),
('2sa-7-26','2sa','사무엘하',7,26,'사람이 영원히 주의 이름을 크게 높여 이르기를 만군의 여호와는 이스라엘의 하나님이라 하게 하옵시며 주의 종 다윗의 집이 주 앞에 견고하게 하옵소서',8207),
('2sa-7-27','2sa','사무엘하',7,27,'만군의 여호와 이스라엘의 하나님이여 주의 종의 귀를 여시고 이르시기를 내가 너를 위하여 집을 세우리라 하셨으므로 주의 종이 이 기도로 주께 간구할 마음이 생겼나이다',8208),
('2sa-7-28','2sa','사무엘하',7,28,'주 여호와여 오직 주는 하나님이시며 주의 말씀들이 참되시니이다 주께서 이 좋은 것을 주의 종에게 말씀하셨사오니',8209),
('2sa-7-29','2sa','사무엘하',7,29,'이제 청하건대 종의 집에 복을 주사 주 앞에 영원히 있게 하옵소서 주 여호와께서 말씀하셨사오니 주의 종의 집이 영원히 복을 받게 하옵소서 하니라',8210),
('2sa-8-1','2sa','사무엘하',8,1,'그 후에 다윗이 블레셋 사람들을 쳐서 항복을 받고 블레셋 사람들의 손에서 메덱암마를 빼앗으니라',8211),
('2sa-8-2','2sa','사무엘하',8,2,'다윗이 또 모압을 쳐서 그들에게 땅에 엎드리게 하고 줄로 재어 그 두 줄 길이의 사람은 죽이고 한 줄 길이의 사람들은 살리니 모압 사람들이 다윗의 종들이 되어 조공을 드리니라',8212),
('2sa-8-3','2sa','사무엘하',8,3,'르홉의 아들 소바 왕 하닷에셀이 자기 권세를 회복하려고 유브라데 강으로 갈 때에 다윗이 그를 쳐서',8213),
('2sa-8-4','2sa','사무엘하',8,4,'그에게서 마병 천칠백 명과 보병 이만 명을 사로잡고 병거 일백 대의 말만 남기고 다윗이 그 외의 병거의 말은 다 발의 힘줄을 끊었더니',8214),
('2sa-8-5','2sa','사무엘하',8,5,'다메섹의 아람 사람들이 소바 왕 하닷에셀을 도우러 온지라 다윗이 아람 사람 이만 이천 명을 죽이고',8215),
('2sa-8-6','2sa','사무엘하',8,6,'다윗이 다메섹 아람에 수비대를 두매 아람 사람이 다윗의 종이 되어 조공을 바치니라 다윗이 어디로 가든지 여호와께서 이기게 하시니라',8216),
('2sa-8-7','2sa','사무엘하',8,7,'다윗이 하닷에셀의 신복들이 가진 금 방패를 빼앗아 예루살렘으로 가져오고',8217),
('2sa-8-8','2sa','사무엘하',8,8,'또 다윗 왕이 하닷에셀의 고을 베다와 베로대에서 매우 많은 놋을 빼앗으니라',8218),
('2sa-8-9','2sa','사무엘하',8,9,'하맛 왕 도이가 다윗이 하닷에셀의 온 군대를 쳐서 무찔렀다 함을 듣고',8219),
